(4729615, 681170, 72929, '<td valign="top">Yikes, overdid it with the background blur... not sure how you stayed within the basic editing rules... lighting is interesting with the sun as fill and fill flash. The pose.. not sure about.</td>', 'Yikes, overdid it with the background blur... not sure how you stayed within the basic editing rules... lighting is interesting with the sun as fill and fill flash. The pose.. not sure about.', '2008-05-28 10:22:48.000000', NULL, 1),
(4729616, 682389, 72929, '<td valign="top">Don''t like the neck rolls and the fact that she''s not looking at the camera.</td>', 'Don''t like the neck rolls and the fact that she''s not looking at the camera.', '2008-05-28 10:23:09.000000', NULL, 1),
(4729617, 682940, 72929, '<td valign="top">OK pose, I dunno about the head tilt and her expression. Lighting is a little flat.</td>', 'OK pose, I dunno about the head tilt and her expression. Lighting is a little flat.', '2008-05-28 10:23:56.000000', NULL, 1),
(4729618, 681814, 18080, '<td valign="top">Well this is my favorite by far for this challenge.<br/>I love it<br/>I love the black and white conversion.<br/>Pose is spot on.<br/>Hope to see this take a ribbon.<br/> <br/>Good luck<br/> <br/>Kev</td>', 'Well this is my favorite by far for this challenge.I love itI love the black and white conversion.Pose is spot on.Hope to see this take a ribbon. Good luck Kev', '2008-05-28 10:24:32.000000', NULL, 1),
(4729620, 682944, 72929, '<td valign="top">Looks a little underexposed on my monitor. Lighting seems to be coming from underneath which puts odd shadows on her face (see her chin).</td>', 'Looks a little underexposed on my monitor. Lighting seems to be coming from underneath which puts odd shadows on her face (see her chin).', '2008-05-28 10:24:49.000000', NULL, 1),
(4729623, 682973, 72929, '<td valign="top">Light is harsh, gives her face too much texture on the cheeks. I would''ve turned her so the sun was to the side or behind and used fill flash or a reflector. Composition and pose are spot on though.</td>', 'Light is harsh, gives her face too much texture on the cheeks. I would''ve turned her so the sun was to the side or behind and used fill flash or a reflector. Composition and pose are spot on though.', '2008-05-28 10:25:58.000000', NULL, 1),
(4729625, 682879, 72929, '<td valign="top">Not looking at camera; candle distracts from her face; can only see one eye.</td>', 'Not looking at camera; candle distracts from her face; can only see one eye.', '2008-05-28 10:26:31.000000', NULL, 1),
(4729626, 682473, 72929, '<td valign="top">Clever.. took me a second.</td>', 'Clever.. took me a second.', '2008-05-28 10:26:46.000000', NULL, 1);
