(4729627, 681508, 72929, '<td valign="top">Tilt doesn''t work for me here. Too much</td>', 'Tilt doesn''t work for me here. Too much', '2008-05-28 10:27:07.000000', NULL, 1),
(4729629, 682932, 72929, '<td valign="top">Visually my eyes are definitely drawn to hers.. bravo on that... then they wander to her fingertips which are also in the focal plane.. boo on that. Close, but not perfect..</td>', 'Visually my eyes are definitely drawn to hers.. bravo on that... then they wander to her fingertips which are also in the focal plane.. boo on that. Close, but not perfect..', '2008-05-28 10:28:23.000000', NULL, 1),
