(4729811, 682976, 72929, '<td valign="top">I''m sure all the crass minded folks are thinking "...or too young". Nice comp but not enough fill light. Her face is lost in the darkness.</td>', 'I''m sure all the crass minded folks are thinking "...or too young". Nice comp but not enough fill light. Her face is lost in the darkness.', '2008-05-28 10:51:51.000000', NULL, 1),
(4729817, 682919, 72929, '<td valign="top">Nice pose, expression, composition and eye contact. Colors are a bit on the cool side.</td>', 'Nice pose, expression, composition and eye contact. Colors are a bit on the cool side.', '2008-05-28 10:52:33.000000', NULL, 1),
