(4729880, 682563, 72929, '<td valign="top">selective color = blech. You shoot this in IR- Her skin is unusually glowy... I bet the uneducated will cry DNMC... Overall the photo is too dark and her lips are green.</td>', 'selective color = blech. You shoot this in IR- Her skin is unusually glowy... I bet the uneducated will cry DNMC... Overall the photo is too dark and her lips are green.', '2008-05-28 11:03:24.000000', NULL, 1),
(4729881, 682976, 9684, '<td valign="top">looks like she is wondering where her youth went</td>', 'looks like she is wondering where her youth went', '2008-05-28 11:03:35.000000', NULL, 1),
(4729887, 682286, 72929, '<td valign="top">Woulve been better if she or the reflection were looking at the camera. Colors seem a little yellow/green to me. I like the lighting. She''ll get tons of views and extra points because of her looks and outfit.</td>', 'Woulve been better if she or the reflection were looking at the camera. Colors seem a little yellow/green to me. I like the lighting. She''ll get tons of views and extra points because of her looks and outfit.', '2008-05-28 11:05:44.000000', NULL, 1),
(4729911, 682233, 88352, '<td valign="top">Fantastic available light portrait</td>', 'Fantastic available light portrait', '2008-05-28 11:20:22.000000', NULL, 1),
