(4729956, 682887, 90173, '<td valign="top">beautyful kid that you got here ;)</td>', 'beautyful kid that you got here ;)', '2008-05-28 11:55:18.000000', NULL, 1),
(4729958, 682522, 58457, '<td valign="top">Would have liked to see the BG highlights toned down a bit--perhaps a fill flash on the face?</td>', 'Would have liked to see the BG highlights toned down a bit--perhaps a fill flash on the face?', '2008-05-28 11:56:03.000000', NULL, 1),
