(4729977, 681426, 58457, '<td valign="top">I''d like more contrast</td>', 'I''d like more contrast', '2008-05-28 12:00:30.000000', NULL, 1),
(4729978, 682739, 58457, '<td valign="top">the lighting comes off a bit harsh.</td>', 'the lighting comes off a bit harsh.', '2008-05-28 12:00:59.000000', NULL, 1),
