(4732284, 681740, 93943, '<td valign="top">This is one of my favorite shots of the challenge.  I would like to see a bit tighter crop on the top and right side would help.</td>', 'This is one of my favorite shots of the challenge.  I would like to see a bit tighter crop on the top and right side would help.', '2008-05-29 07:11:51.000000', NULL, 1),
(4732285, 682286, 11518, '<td valign="top">Wow, beautiful portrait, great light, great expression, love the reflection and the light is perfect!  Front page material for sure. 10</td>', 'Wow, beautiful portrait, great light, great expression, love the reflection and the light is perfect!  Front page material for sure. 10', '2008-05-29 07:17:23.000000', NULL, 1),
(4732287, 682687, 11518, '<td valign="top">Great pose and location.  But the blown highlight is very distracting.  The only way to avoid this would have been to expose for the highlight and fill in the shadows with a strobe or reflector.</td>', 'Great pose and location.  But the blown highlight is very distracting.  The only way to avoid this would have been to expose for the highlight and fill in the shadows with a strobe or reflector.', '2008-05-29 07:20:26.000000', NULL, 1),
(4732289, 682422, 93943, '<td valign="top">Interesting photo</td>', 'Interesting photo', '2008-05-29 07:22:30.000000', NULL, 1),
(4732290, 682889, 11518, '<td valign="top">ROFL, very very cute! great expression!  Beautiful catchlights.</td>', 'ROFL, very very cute! great expression!  Beautiful catchlights.', '2008-05-29 07:22:53.000000', NULL, 1),
(4732293, 681614, 11518, '<td valign="top">Nice even light.  I would have cropped out the left side.</td>', 'Nice even light.  I would have cropped out the left side.', '2008-05-29 07:25:15.000000', NULL, 1),
(4732295, 682924, 11518, '<td valign="top">Beautiful fun pose. Unfortunately her eyes are not in focus.  Looks like the camera locked focus on her collar.</td>', 'Beautiful fun pose. Unfortunately her eyes are not in focus.  Looks like the camera locked focus on her collar.', '2008-05-29 07:31:00.000000', NULL, 1),
(4732297, 682939, 11518, '<td valign="top">Love the bokeh, expression and composition.  The reddish color cast bugs me a bit, I would have liked the color to be more on the natural side.  Still this is a good effort! 6</td>', 'Love the bokeh, expression and composition.  The reddish color cast bugs me a bit, I would have liked the color to be more on the natural side.  Still this is a good effort! 6', '2008-05-29 07:33:43.000000', NULL, 1),
(4732298, 682621, 79955, '<td valign="top">Need to reduce the shadows around the neck area.<br/>Need to try to capture the eyes with catchlights.<br/>The overall color tone a little on the yellowish side</td>', 'Need to reduce the shadows around the neck area.Need to try to capture the eyes with catchlights.The overall color tone a little on the yellowish side', '2008-05-29 07:35:11.000000', NULL, 1),
(4732299, 681049, 93943, '<td valign="top">I like the concept a lot.  I am not sure if you cropped it out of a much lager photo or what, but the quality is a bit low.</td>', 'I like the concept a lot.  I am not sure if you cropped it out of a much lager photo or what, but the quality is a bit low.', '2008-05-29 07:35:36.000000', NULL, 1),
(4732300, 682018, 11518, '<td valign="top">She has a beautiful expressive face.  I would have composed the shot tighter and filling the frame with her face.  The squished left boob gives this shot an awkward look.  Great tattoos.  Great light. 6</td>', 'She has a beautiful expressive face.  I would have composed the shot tighter and filling the frame with her face.  The squished left boob gives this shot an awkward look.  Great tattoos.  Great light. 6', '2008-05-29 07:36:11.000000', NULL, 1);
