(4735279, 682218, 90414, '<td valign="top">Nice catchlight in those beautiful eyes. Great fullframe.</td>', 'Nice catchlight in those beautiful eyes. Great fullframe.', '2008-05-30 22:43:54.000000', NULL, 1),
(4735280, 682940, 33672, '<td valign="top">Very well composed.</td>', 'Very well composed.', '2008-05-30 22:44:29.000000', NULL, 1),
