INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4735360, 682935, 88204, '<td valign="top">Beautiful lighting! Nice expression and environment. Depth of field is nice to simplify. Well done!</td>', 'Beautiful lighting! Nice expression and environment. Depth of field is nice to simplify. Well done!', '2008-05-30 23:22:44.000000', NULL, 1),
(4735366, 682630, 90947, '<td valign="top">I see the glass.  I see a lovely lady well lit for a low key portrait.  I don''t understand the relationship between them.  I don''t know what is to be the focus here.  Perhaps her face could be a bit lighter if she is to be the subject of this photograph.</td>', 'I see the glass.  I see a lovely lady well lit for a low key portrait.  I don''t understand the relationship between them.  I don''t know what is to be the focus here.  Perhaps her face could be a bit lighter if she is to be the subject of this photograph.', '2008-05-30 23:24:47.000000', NULL, 1),
(4735370, 682895, 90947, '<td valign="top">Lovely young lady.  Unfortunately this seem to be a little out of focus and the very bright, very out of focus background, brings in a classic example of purple plague.. or green plague in this case.</td>', 'Lovely young lady.  Unfortunately this seem to be a little out of focus and the very bright, very out of focus background, brings in a classic example of purple plague.. or green plague in this case.', '2008-05-30 23:26:41.000000', NULL, 1),
(4735374, 682923, 88204, '<td valign="top">I love the limited color pallette and shallow depth of field. Nice soft smile. Framing is interesting having her off to the right facing the right... I would expect her to be more to the left... I like that it''s an unusual crop. One of my favorites.</td>', 'I love the limited color pallette and shallow depth of field. Nice soft smile. Framing is interesting having her off to the right facing the right... I would expect her to be more to the left... I like that it''s an unusual crop. One of my favorites.', '2008-05-30 23:28:41.000000', NULL, 1),
(4735376, 682899, 90947, '<td valign="top">What a lovely young lady.  Good shot, perfectly exposed and sharp as a knife.  The background is nicely out of focus.  I wonder what she is going to think of this shot after she gets her braces off... just musing.</td>', 'What a lovely young lady.  Good shot, perfectly exposed and sharp as a knife.  The background is nicely out of focus.  I wonder what she is going to think of this shot after she gets her braces off... just musing.', '2008-05-30 23:28:46.000000', NULL, 1),
(4735384, 682862, 90947, '<td valign="top">Good sepia tone shot.  I think I would have made an effort to remove whatever was casting the shadow on the models right arm.</td>', 'Good sepia tone shot.  I think I would have made an effort to remove whatever was casting the shadow on the models right arm.', '2008-05-30 23:31:26.000000', NULL, 1),
(4735388, 682919, 88204, '<td valign="top">I love it how the eyes are in the darkness of the visor yet still bright enough. Lighting is very even. Nice catch light in the eyes.</td>', 'I love it how the eyes are in the darkness of the visor yet still bright enough. Lighting is very even. Nice catch light in the eyes.', '2008-05-30 23:33:29.000000', NULL, 1),
(4735390, 681072, 88204, '<td valign="top">Great eyes! Love the close crop.</td>', 'Great eyes! Love the close crop.', '2008-05-30 23:34:09.000000', NULL, 1),
(4735394, 682319, 90947, '<td valign="top">I had to look it up: A femme fatale is a sensuous, alluring woman who often leads men into danger ...<br/> <br/>Well, that is this femme in spades.  Love it.  I don''t know if you planned the slight blue color case, but it either works or doesn''t distract.  I haven''t decided.</td>', 'I had to look it up: A femme fatale is a sensuous, alluring woman who often leads men into danger ... Well, that is this femme in spades.  Love it.  I don''t know if you planned the slight blue color case, but it either works or doesn''t distract.  I haven''t decided.', '2008-05-30 23:35:22.000000', NULL, 1),
(4735396, 681049, 88204, '<td valign="top">Very nice shot but it''s coming through very grainy and textured on my monitor. Lighting is nice, expression is nice but I wish it were sharp.</td>', 'Very nice shot but it''s coming through very grainy and textured on my monitor. Lighting is nice, expression is nice but I wish it were sharp.', '2008-05-30 23:36:24.000000', NULL, 1),
(4735399, 682587, 90947, '<td valign="top">How about: "Longing"  She appears to be either longing to be out participating in, or hiding from whatever she is looking at.  Very nice window lighting.</td>', 'How about: "Longing"  She appears to be either longing to be out participating in, or hiding from whatever she is looking at.  Very nice window lighting.', '2008-05-30 23:37:36.000000', NULL, 1),
(4735401, 681964, 88204, '<td valign="top">I LOVE the stare and the beautiful purple framing. Dramatic lighting is perfectly done as well. Wonderful shot! 10</td>', 'I LOVE the stare and the beautiful purple framing. Dramatic lighting is perfectly done as well. Wonderful shot! 10', '2008-05-30 23:38:03.000000', NULL, 1),
(4735402, 682218, 88204, '<td valign="top">Wow! I LOVE the eyes on this shot. It''s so interesting to be so close with very nice sharpness. Lighting is very even. This is my favorite of the challenge! 10</td>', 'Wow! I LOVE the eyes on this shot. It''s so interesting to be so close with very nice sharpness. Lighting is very even. This is my favorite of the challenge! 10', '2008-05-30 23:38:19.000000', NULL, 1),
(4735410, 682012, 90947, '<td valign="top">Nice control of the light essentially cutting Lindsay''s face in half.  I like the effect.  I might have tried to move the hair that is casting the shadow on her cheek.  Nice sharp focus for her eye.</td>', 'Nice control of the light essentially cutting Lindsay''s face in half.  I like the effect.  I might have tried to move the hair that is casting the shadow on her cheek.  Nice sharp focus for her eye.', '2008-05-30 23:41:31.000000', NULL, 1),
(4735415, 682746, 90947, '<td valign="top">Freckled faced kids are great.  Perfect exposure and lighting.</td>', 'Freckled faced kids are great.  Perfect exposure and lighting.', '2008-05-30 23:43:09.000000', NULL, 1),
(4735421, 682884, 90947, '<td valign="top">Nicely posed and lit.  The background still has texture, which while non-discript might have been underexposed to pure black.  Great lighting of Kaitlin.</td>', 'Nicely posed and lit.  The background still has texture, which while non-discript might have been underexposed to pure black.  Great lighting of Kaitlin.', '2008-05-30 23:45:30.000000', NULL, 1),
(4735426, 682958, 90947, '<td valign="top">Interesting color balance.  It makes me think of pictures of me some 55 years ago.  I like the feeling.  Perhaps the lighting is casting an excessively sharp shadow.  Very cute.</td>', 'Interesting color balance.  It makes me think of pictures of me some 55 years ago.  I like the feeling.  Perhaps the lighting is casting an excessively sharp shadow.  Very cute.', '2008-05-30 23:47:58.000000', NULL, 1),
(4735434, 682688, 90947, '<td valign="top">Very cute little girl, and freckles are always great.  Perfect focus and nice soft lighting.</td>', 'Very cute little girl, and freckles are always great.  Perfect focus and nice soft lighting.', '2008-05-30 23:50:11.000000', NULL, 1),
(4735436, 681573, 60828, '<td valign="top">I wonder what she is thinking - maybe why do you have a camera in my face:)</td>', 'I wonder what she is thinking - maybe why do you have a camera in my face:)', '2008-05-30 23:50:56.000000', NULL, 1),
(4735438, 682653, 90947, '<td valign="top">I really like the B&amp;W choice here.  I think the fabric in the foreground and the light spot in the upper right hand corner are a bit distracting.  Overall, very nice.</td>', 'I really like the B&W choice here.  I think the fabric in the foreground and the light spot in the upper right hand corner are a bit distracting.  Overall, very nice.', '2008-05-30 23:52:13.000000', NULL, 1),
(4735439, 681614, 60828, '<td valign="top">I like this shot, however maybe bit closer to pop her eyes.</td>', 'I like this shot, however maybe bit closer to pop her eyes.', '2008-05-30 23:52:17.000000', NULL, 1),
(4735446, 682520, 60828, '<td valign="top">Very cute - I''d glow it a bit, it would be nice to see her smile better</td>', 'Very cute - I''d glow it a bit, it would be nice to see her smile better', '2008-05-30 23:54:00.000000', NULL, 1),
(4735451, 680737, 60828, '<td valign="top">Very wonderful image!</td>', 'Very wonderful image!', '2008-05-30 23:55:58.000000', NULL, 1),
(4735452, 682728, 90947, '<td valign="top">I passed by Pam''s photo several times because I had to let it soak in.  Observations: It appears to have been taken with a very short focal length lens; nothing wrong with that.  The tree is providing dappled light; very nice.  Very pretty lady with a lovely smile.  I guess I like it, a lot.</td>', 'I passed by Pam''s photo several times because I had to let it soak in.  Observations: It appears to have been taken with a very short focal length lens; nothing wrong with that.  The tree is providing dappled light; very nice.  Very pretty lady with a lovely smile.  I guess I like it, a lot.', '2008-05-30 23:56:06.000000', NULL, 1),
(4735456, 682393, 90947, '<td valign="top">Very artistic cropping, lighting, choice of black and white.  I wish there was more life (catch light) in the remaining eye.</td>', 'Very artistic cropping, lighting, choice of black and white.  I wish there was more life (catch light) in the remaining eye.', '2008-05-30 23:58:07.000000', NULL, 1),
(4735458, 682286, 60828, '<td valign="top">Love the shot - it should do very well.  Is the flash also captured in the glass?</td>', 'Love the shot - it should do very well.  Is the flash also captured in the glass?', '2008-05-30 23:59:23.000000', NULL, 1),
(4735460, 682685, 90947, '<td valign="top">Beautiful lady, great smile, perfect teeth, gorgeous hair... this is a very engaging portrait.</td>', 'Beautiful lady, great smile, perfect teeth, gorgeous hair... this is a very engaging portrait.', '2008-05-30 23:59:36.000000', NULL, 1),
(4735464, 682356, 90947, '<td valign="top">To me, this is a very nice perspective for your portrait.  I like the very tight crop.  I think the focus on the eyes could have been a little sharper, but it may look like this because of the low resolution.  While I am sure you would never have seen it in the viewfinder, I think that the single hairs would be better gone.</td>', 'To me, this is a very nice perspective for your portrait.  I like the very tight crop.  I think the focus on the eyes could have been a little sharper, but it may look like this because of the low resolution.  While I am sure you would never have seen it in the viewfinder, I think that the single hairs would be better gone.', '2008-05-31 00:02:55.000000', NULL, 1),
(4735466, 682920, 90947, '<td valign="top">very nice snapshot of a beautiful little girl.  You caught a great expression.</td>', 'very nice snapshot of a beautiful little girl.  You caught a great expression.', '2008-05-31 00:03:49.000000', NULL, 1),
(4735468, 682944, 90947, '<td valign="top">This appears to be a very professional quality portrait.  Everything is right: lighting, focus, DOF, expression.. everything is just right.</td>', 'This appears to be a very professional quality portrait.  Everything is right: lighting, focus, DOF, expression.. everything is just right.', '2008-05-31 00:05:14.000000', NULL, 1),
(4735478, 682248, 90947, '<td valign="top">Nice shot of a very friendly appearing lady.</td>', 'Nice shot of a very friendly appearing lady.', '2008-05-31 00:13:56.000000', NULL, 1),
(4735480, 682732, 90947, '<td valign="top">"Kilroy was here."  Very pretty girl with a wonderful smile.  Good DOF.  I might have moved in a little closer showing less of the wall.  That would probably require her hands to come a little closer together, but this is a picture of Selina, not a wall.</td>', '"Kilroy was here."  Very pretty girl with a wonderful smile.  Good DOF.  I might have moved in a little closer showing less of the wall.  That would probably require her hands to come a little closer together, but this is a picture of Selina, not a wall.', '2008-05-31 00:17:24.000000', NULL, 1),
(4735482, 681814, 60828, '<td valign="top">I like this shot - I''d like to see the other eye covered a bit more and less contrast.</td>', 'I like this shot - I''d like to see the other eye covered a bit more and less contrast.', '2008-05-31 00:17:40.000000', NULL, 1),
(4735483, 682587, 60828, '<td valign="top">She looks very pretty, you will score better with a title.</td>', 'She looks very pretty, you will score better with a title.', '2008-05-31 00:19:35.000000', NULL, 1),
(4735485, 682473, 90947, '<td valign="top">I really like this picture.  I like the contrast of the warm, soft, alive hand and the cold, hard, stone of the head.  As much as I like it, I am not sure it is completely in concert with the challenge.</td>', 'I really like this picture.  I like the contrast of the warm, soft, alive hand and the cold, hard, stone of the head.  As much as I like it, I am not sure it is completely in concert with the challenge.', '2008-05-31 00:20:16.000000', NULL, 1),
(4735487, 680956, 60828, '<td valign="top">Now thats a happy bady!</td>', 'Now thats a happy bady!', '2008-05-31 00:21:02.000000', NULL, 1),
(4735488, 681999, 60828, '<td valign="top">Very interesting shot, needs a bit more contrast.</td>', 'Very interesting shot, needs a bit more contrast.', '2008-05-31 00:22:08.000000', NULL, 1),
(4735490, 682389, 90947, '<td valign="top">Very nice nearly over the shoulder shot. I like the nearly B&amp;W flat lighting.  Did you intend it to have a slight pink color cast?</td>', 'Very nice nearly over the shoulder shot. I like the nearly B&W flat lighting.  Did you intend it to have a slight pink color cast?', '2008-05-31 00:22:53.000000', NULL, 1),
