(4735533, 682932, 88054, '<td valign="top">A little side lighting would add more depth to her face, still...Her eyes are captivating. One of my favorite. Very well done.</td>', 'A little side lighting would add more depth to her face, still...Her eyes are captivating. One of my favorite. Very well done.', '2008-05-31 00:39:49.000000', NULL, 1),
(4735535, 682919, 88054, '<td valign="top">She''s beautiful. Nicely done.</td>', 'She''s beautiful. Nicely done.', '2008-05-31 00:40:30.000000', NULL, 1),
