INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4736386, 682220, 19310, '<td valign="top">This is the first kid picture I don''t like all that much.  Kids need to be very light or lite and lively  Give her more light.</td>', 'This is the first kid picture I don''t like all that much.  Kids need to be very light or lite and lively  Give her more light.', '2008-05-31 17:08:10.000000', NULL, 1),
(4736392, 682579, 19310, '<td valign="top">Bad choice of a title for such a beauty</td>', 'Bad choice of a title for such a beauty', '2008-05-31 17:16:33.000000', NULL, 1),
(4736393, 682965, 19310, '<td valign="top">Excellent portrait and lighting in my 40 years as a professional photographer I do like this one.  The only thing is the brightness of the leg could cool it down somewhat.</td>', 'Excellent portrait and lighting in my 40 years as a professional photographer I do like this one.  The only thing is the brightness of the leg could cool it down somewhat.', '2008-05-31 17:18:40.000000', NULL, 1),
(4736398, 682796, 19310, '<td valign="top">When I first looked at this I said "what the hell" something different with lots of action</td>', 'When I first looked at this I said "what the hell" something different with lots of action', '2008-05-31 17:20:10.000000', NULL, 1),
(4736401, 682119, 19310, '<td valign="top">Beauty in study play of light</td>', 'Beauty in study play of light', '2008-05-31 17:20:51.000000', NULL, 1),
(4736435, 682841, 93386, '<td valign="top">Nice image - nice light. I would prefer to exclude the mound in the background.</td>', 'Nice image - nice light. I would prefer to exclude the mound in the background.', '2008-05-31 17:55:10.000000', NULL, 1),
(4736436, 681999, 93386, '<td valign="top">Good capture. Needs more contrast.</td>', 'Good capture. Needs more contrast.', '2008-05-31 17:56:30.000000', NULL, 1),
(4736438, 682563, 93386, '<td valign="top">Love the limited use of colour. I was expecting her lips to be coloured too.</td>', 'Love the limited use of colour. I was expecting her lips to be coloured too.', '2008-05-31 17:57:53.000000', NULL, 1),
(4736441, 682739, 93386, '<td valign="top">Striking! Needs more depth of field to bring the word into focus too. Also it would be nice - though probably tricky - to get both the folds of the book spine to point at each of her eyes.</td>', 'Striking! Needs more depth of field to bring the word into focus too. Also it would be nice - though probably tricky - to get both the folds of the book spine to point at each of her eyes.', '2008-05-31 18:00:39.000000', NULL, 1),
(4736443, 682725, 93386, '<td valign="top">Amazing quality in this image.</td>', 'Amazing quality in this image.', '2008-05-31 18:01:40.000000', NULL, 1),
(4736445, 682926, 93386, '<td valign="top">Really good image but the horizon is not level. You can correct this easily in Adobe Photoshop Elements.</td>', 'Really good image but the horizon is not level. You can correct this easily in Adobe Photoshop Elements.', '2008-05-31 18:02:58.000000', NULL, 1),
(4736448, 681700, 93386, '<td valign="top">As a snap-shot this is really striking.</td>', 'As a snap-shot this is really striking.', '2008-05-31 18:04:03.000000', NULL, 1),
(4736451, 681190, 93386, '<td valign="top">The reduced contrast really works for me. This is a beautiful shot.</td>', 'The reduced contrast really works for me. This is a beautiful shot.', '2008-05-31 18:06:04.000000', NULL, 1),
(4736456, 682973, 93386, '<td valign="top">Attractive girl. However, the strong light is not to my taste. It would be nice if her eye pupils were a little more dilated - they have closed up because of the bright sunlight.</td>', 'Attractive girl. However, the strong light is not to my taste. It would be nice if her eye pupils were a little more dilated - they have closed up because of the bright sunlight.', '2008-05-31 18:08:43.000000', NULL, 1),
(4736458, 682687, 93386, '<td valign="top">Exposed for the shadows - I admire you technique. A beautiful photograph. Possibly closer to a fashion shot than a portrait IMHO.</td>', 'Exposed for the shadows - I admire you technique. A beautiful photograph. Possibly closer to a fashion shot than a portrait IMHO.', '2008-05-31 18:11:08.000000', NULL, 1),
(4736460, 682889, 93386, '<td valign="top">That is such a fun shot - is it candid or did you take lots?</td>', 'That is such a fun shot - is it candid or did you take lots?', '2008-05-31 18:11:54.000000', NULL, 1),
(4736464, 682431, 93386, '<td valign="top">The colourful background and the light &amp; shade on the model really work well.</td>', 'The colourful background and the light & shade on the model really work well.', '2008-05-31 18:13:48.000000', NULL, 1),
(4736467, 682716, 93386, '<td valign="top">The title is just right for the image.</td>', 'The title is just right for the image.', '2008-05-31 18:14:57.000000', NULL, 1),
(4736471, 681049, 93386, '<td valign="top">Resolution is too low. That is a shame as this could be a really nice portrait otherwise.</td>', 'Resolution is too low. That is a shame as this could be a really nice portrait otherwise.', '2008-05-31 18:16:32.000000', NULL, 1),
(4736474, 682351, 93386, '<td valign="top">This is looking into a mirror? It could be twins!</td>', 'This is looking into a mirror? It could be twins!', '2008-05-31 18:17:55.000000', NULL, 1),
(4736476, 681577, 93386, '<td valign="top">More hen than chick I think!</td>', 'More hen than chick I think!', '2008-05-31 18:19:00.000000', NULL, 1),
(4736480, 681508, 93386, '<td valign="top">I like the diagonal composition with the strips. It really makes the image stand out. -- She plays the Uke?</td>', 'I like the diagonal composition with the strips. It really makes the image stand out. -- She plays the Uke?', '2008-05-31 18:20:57.000000', NULL, 1),
(4736482, 682217, 93386, '<td valign="top">My personal taste is for a bit more contrast in black &amp; white. Very sharp. Lots of detail. Beautiful.</td>', 'My personal taste is for a bit more contrast in black & white. Very sharp. Lots of detail. Beautiful.', '2008-05-31 18:22:32.000000', NULL, 1),
(4736490, 682796, 93386, '<td valign="top">Brave model! You have made the swirls over her body match the swirls of her hair style which I like. The green of her breasts seems to match the green of the trees. I would like the shot to be closer to the model and from a lower angle so there is less road behind her. It is a liberal interpretation of "portrait".</td>', 'Brave model! You have made the swirls over her body match the swirls of her hair style which I like. The green of her breasts seems to match the green of the trees. I would like the shot to be closer to the model and from a lower angle so there is less road behind her. It is a liberal interpretation of "portrait".', '2008-05-31 18:28:59.000000', NULL, 1),
(4736492, 681814, 93386, '<td valign="top">Her hair frames her face very well.</td>', 'Her hair frames her face very well.', '2008-05-31 18:30:19.000000', NULL, 1),
(4736495, 682145, 93386, '<td valign="top">Diagonal definitely adds a dynamic something. The colours need to be brighter.</td>', 'Diagonal definitely adds a dynamic something. The colours need to be brighter.', '2008-05-31 18:32:49.000000', NULL, 1),
(4736496, 682703, 10818, '<td valign="top">Did she hook up with Yao Ming?<br/>She has a sweet smile and looks quite happy.</td>', 'Did she hook up with Yao Ming?She has a sweet smile and looks quite happy.', '2008-05-31 18:33:20.000000', NULL, 1),
(4736497, 682597, 93386, '<td valign="top">No please! Loose the can. I like the high camera angle.</td>', 'No please! Loose the can. I like the high camera angle.', '2008-05-31 18:34:16.000000', NULL, 1),
(4736498, 682944, 10818, '<td valign="top">Really pretty photo, colors are warm and enticing.<br/>The hand gives some balance, but looks awkward in this shot.</td>', 'Really pretty photo, colors are warm and enticing.The hand gives some balance, but looks awkward in this shot.', '2008-05-31 18:36:17.000000', NULL, 1),
(4736499, 681170, 93386, '<td valign="top">Strong colours. My attention is held by her clothes instead of herself.</td>', 'Strong colours. My attention is held by her clothes instead of herself.', '2008-05-31 18:36:48.000000', NULL, 1),
