(4736503, 682899, 10818, '<td valign="top">She looks so sweet, wonderful shot.</td>', 'She looks so sweet, wonderful shot.', '2008-05-31 18:38:56.000000', NULL, 1),
(4736504, 681765, 93386, '<td valign="top">I bet you can''t tell if it a girl or boy ladybird!!! (You might need a microscope for that!)</td>', 'I bet you can''t tell if it a girl or boy ladybird!!! (You might need a microscope for that!)', '2008-05-31 18:39:14.000000', NULL, 1),
