(4739627, 682468, 89774, '<td valign="top">Simple and beautiful - great capture!</td>', 'Simple and beautiful - great capture!', '2008-06-01 19:53:23.000000', NULL, 1),
(4739632, 682903, 89774, '<td valign="top">Love the colors and unusual crop - it doesn''t really bother me that the hand isn''t all there. I feel like the eyes may be a smidge too close to the top, but it still works. Well done!</td>', 'Love the colors and unusual crop - it doesn''t really bother me that the hand isn''t all there. I feel like the eyes may be a smidge too close to the top, but it still works. Well done!', '2008-06-01 19:55:06.000000', NULL, 1),
(4739633, 682935, 89774, '<td valign="top">I really like this one! :)</td>', 'I really like this one! :)', '2008-06-01 19:55:32.000000', NULL, 1),
(4739634, 682968, 89774, '<td valign="top">Beautiful!</td>', 'Beautiful!', '2008-06-01 19:55:41.000000', NULL, 1),
(4739636, 682923, 89774, '<td valign="top">Love the brokeh - really works!</td>', 'Love the brokeh - really works!', '2008-06-01 19:56:02.000000', NULL, 1),
(4739637, 682790, 89774, '<td valign="top">Great shot!</td>', 'Great shot!', '2008-06-01 19:56:11.000000', NULL, 1),
