(4746708, 682948, 35804, '<td valign="top">Oh nu-uh! Lucky thirteens all around! Actually wanted to see this higher though.<br/> <br/>Awesome shot M!</td>', 'Oh nu-uh! Lucky thirteens all around! Actually wanted to see this higher though. Awesome shot M!', '2008-06-04 01:10:47.000000', NULL, 0),
(4746712, 681964, 45475, '<td valign="top">Oh wow... stunning shot Marac, congrats on the red :) Hello Hanae!</td>', 'Oh wow... stunning shot Marac, congrats on the red :) Hello Hanae!', '2008-06-04 01:11:15.000000', NULL, 0),
(4746719, 681964, 66192, '<td valign="top">Great shot! The catch lights are throwing me off when trying to figure out your lighting. Please tell.</td>', 'Great shot! The catch lights are throwing me off when trying to figure out your lighting. Please tell.', '2008-06-04 01:12:21.000000', NULL, 0),
(4746724, 682903, 49643, '<td valign="top">Congratulations on top 5 finish! You proved me wrong but I really didn''t like the cropped fingers.</td>', 'Congratulations on top 5 finish! You proved me wrong but I really didn''t like the cropped fingers.', '2008-06-04 01:12:57.000000', NULL, 0),
(4746727, 682687, 54645, '<td valign="top">Wow, I thought this would easily hit the top 10. Maybe the hightlights were too much, although I feel that it frames her nicely.. I don''t understand the 31 sub 5 votes!</td>', 'Wow, I thought this would easily hit the top 10. Maybe the hightlights were too much, although I feel that it frames her nicely.. I don''t understand the 31 sub 5 votes!', '2008-06-04 01:13:34.000000', NULL, 0),
(4746729, 682319, 11518, '<td valign="top">Underrated.</td>', 'Underrated.', '2008-06-04 01:13:47.000000', NULL, 0),
(4746744, 682766, 89940, '<td valign="top">I''m surprised this didn''t score higher. It''s a very nice shot, nice pose, and even more impressive knowing it''s a self-portrait.</td>', 'I''m surprised this didn''t score higher. It''s a very nice shot, nice pose, and even more impressive knowing it''s a self-portrait.', '2008-06-04 01:16:26.000000', NULL, 0),
(4746753, 682685, 56880, '<td valign="top">I can''t fault you for lacking catchlights, given the dark eyes in my own entry.  The tight crop makes the face appear squished to me.  You did get nice natural light in the hair, giving it a nice texture to contrast with her skin.</td>', 'I can''t fault you for lacking catchlights, given the dark eyes in my own entry.  The tight crop makes the face appear squished to me.  You did get nice natural light in the hair, giving it a nice texture to contrast with her skin.', '2008-06-04 01:18:02.000000', NULL, 0),
(4746754, 681814, 61961, '<td valign="top">So happy this made the top 10 as it was one of my two challenge favorites.  Hearing this is a "candid" makes sense: you caught a beautiful, vulnerable expression.</td>', 'So happy this made the top 10 as it was one of my two challenge favorites.  Hearing this is a "candid" makes sense: you caught a beautiful, vulnerable expression.', '2008-06-04 01:18:04.000000', NULL, 0),
(4746755, 682923, 67697, '<td valign="top">Excellent!  I knew this was good.  Congrats on 9th place and your new 3rd PB!</td>', 'Excellent!  I knew this was good.  Congrats on 9th place and your new 3rd PB!', '2008-06-04 01:18:12.000000', NULL, 0),
(4746760, 682018, 61961, '<td valign="top">Congratulations on your 4th place; this was one of my two challenge favorites.</td>', 'Congratulations on your 4th place; this was one of my two challenge favorites.', '2008-06-04 01:19:06.000000', NULL, 0),
(4746767, 682688, 56880, '<td valign="top">Ha! What an expression!  I like the diagonal lines of the eyebrows and smirk, but the light on the face looks flat. Nicely chosen crop, framing exactly what you needed of her face.</td>', 'Ha! What an expression!  I like the diagonal lines of the eyebrows and smirk, but the light on the face looks flat. Nicely chosen crop, framing exactly what you needed of her face.', '2008-06-04 01:19:49.000000', NULL, 0),
(4746770, 682940, 67697, '<td valign="top">That''s not too bad of a finish.  I think yours did better than mine lol.  I love her hair!</td>', 'That''s not too bad of a finish.  I think yours did better than mine lol.  I love her hair!', '2008-06-04 01:20:18.000000', NULL, 0),
(4746772, 681814, 48227, '<td valign="top">For me this was the best shot in this challenge.</td>', 'For me this was the best shot in this challenge.', '2008-06-04 01:20:29.000000', NULL, 0),
(4746781, 682932, 90663, '<td valign="top">Great job, beautiful shot and well-deserved ribbon!</td>', 'Great job, beautiful shot and well-deserved ribbon!', '2008-06-04 01:21:46.000000', NULL, 0),
(4746783, 682573, 56880, '<td valign="top">Reading a newspaper?  How very leftist of you(r model)!  This picture tells more of a story than most of the portraits, but the challenge was aimed more at describing a character superficially.  Sitting right of center in your frame is a nice touch.</td>', 'Reading a newspaper?  How very leftist of you(r model)!  This picture tells more of a story than most of the portraits, but the challenge was aimed more at describing a character superficially.  Sitting right of center in your frame is a nice touch.', '2008-06-04 01:22:15.000000', NULL, 0),
(4746785, 682919, 48576, '<td valign="top">A picture taken in our van just after tennis lessons.  She was reading an Archie comic as we waited for my older daughter to finish her lesson, but was patient enough to look up a couple times, and it was the day of the challenge deadline so I wanted a shot.  Jessica is photogenic and makes it easy to get a good pic.  Used a long lense for shallow dof, cropped carefully and that was about it.  Thanks to all for the comments... love getting comments...<br/><br/><i>Message edited by author 2008-06-04 00:27:24.</i></td>', 'A picture taken in our van just after tennis lessons.  She was reading an Archie comic as we waited for my older daughter to finish her lesson, but was patient enough to look up a couple times, and it was the day of the challenge deadline so I wanted a shot.  Jessica is photogenic and makes it easy to get a good pic.  Used a long lense for shallow dof, cropped carefully and that was about it.  Thanks to all for the comments... love getting comments...', '2008-06-04 01:22:20.000000', '2008-06-04 01:27:24.000000', 0),
(4746792, 682014, 58691, '<td valign="top">Sorry for the DQ. Basic editing portraits are tough and almost all portraits require spot editing. This is still an outstanding shot. Well done.</td>', 'Sorry for the DQ. Basic editing portraits are tough and almost all portraits require spot editing. This is still an outstanding shot. Well done.', '2008-06-04 01:23:22.000000', NULL, 0),
(4746793, 681964, 90663, '<td valign="top">I didn''t have enough time to get enough votes in for mine to count, but for what it''s worth this was a definite top ten from the get go, way to go!</td>', 'I didn''t have enough time to get enough votes in for mine to count, but for what it''s worth this was a definite top ten from the get go, way to go!', '2008-06-04 01:23:27.000000', NULL, 0),
(4746800, 682790, 56880, '<td valign="top">I think a sharper picture would not have conveyed the "troubles" of your model.  You did an excellent job with the light, getting just enough fill on the far side of the face to give detail without losing the shaping of the shadows.</td>', 'I think a sharper picture would not have conveyed the "troubles" of your model.  You did an excellent job with the light, getting just enough fill on the far side of the face to give detail without losing the shaping of the shadows.', '2008-06-04 01:24:13.000000', NULL, 0),
(4746802, 682948, 80976, '<td valign="top">13''th? No way! I had this pegged higher, framing and composition are magnificent.</td>', '13''th? No way! I had this pegged higher, framing and composition are magnificent.', '2008-06-04 01:24:21.000000', NULL, 0),
(4746809, 682286, 61961, '<td valign="top">Congratulations on a winning photo!  Somehow this makes me think she is looking out at the ocean.</td>', 'Congratulations on a winning photo!  Somehow this makes me think she is looking out at the ocean.', '2008-06-04 01:25:19.000000', NULL, 0),
(4746819, 682923, 61651, '<td valign="top">Scrumptious DOF choice, really stellar, and that oof background abstraction adds such a liveliness to the shot.  Congratulations Rob on a truly excellent capture!</td>', 'Scrumptious DOF choice, really stellar, and that oof background abstraction adds such a liveliness to the shot.  Congratulations Rob on a truly excellent capture!', '2008-06-04 01:27:29.000000', NULL, 0),
(4746821, 682867, 56880, '<td valign="top">The focus around her eyes does look a little too soft.  The light on the model is flat (in the shade?) and the brightness of the backlit leaves emphasizes this.</td>', 'The focus around her eyes does look a little too soft.  The light on the model is flat (in the shade?) and the brightness of the backlit leaves emphasizes this.', '2008-06-04 01:27:41.000000', NULL, 0),
(4746825, 682923, 60862, '<td valign="top">Woohoo, Rob!  Congrats on a fantastic natural light portrait and top 10, plus your new 3rd-best ever!</td>', 'Woohoo, Rob!  Congrats on a fantastic natural light portrait and top 10, plus your new 3rd-best ever!', '2008-06-04 01:28:33.000000', NULL, 0),
(4746834, 682274, 44877, '<td valign="top">Beautiful photo, Jon. During voting I thought that might be Charlene, and it is. Love the softness and her radiance. Very well captured!!</td>', 'Beautiful photo, Jon. During voting I thought that might be Charlene, and it is. Love the softness and her radiance. Very well captured!!', '2008-06-04 01:29:25.000000', NULL, 0),
(4746835, 682450, 61961, '<td valign="top">This one was definitely underrated.  I love those blues and the someone enigmatic expression of your model.</td>', 'This one was definitely underrated.  I love those blues and the someone enigmatic expression of your model.', '2008-06-04 01:29:28.000000', NULL, 0),
(4746839, 682441, 56880, '<td valign="top">I might have cropped a little off the bottom and the left, but otherwise I really like this shot.</td>', 'I might have cropped a little off the bottom and the left, but otherwise I really like this shot.', '2008-06-04 01:29:58.000000', NULL, 0),
(4746851, 681814, 41337, '<td valign="top"><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by mia67:</b></div><hr/><i> For me this was the best shot in this challenge. </i></td></tr></table> <br/> <br/>Had I voted this would have been my top pick as well.</td>', 'Originally posted by mia67: For me this was the best shot in this challenge.   Had I voted this would have been my top pick as well.', '2008-06-04 01:31:54.000000', NULL, 0),
(4746853, 682579, 56880, '<td valign="top">You got nice catch lights and hair light, but the brightness of the background makes the shade/flat light on the model look that much darker.</td>', 'You got nice catch lights and hair light, but the brightness of the background makes the shade/flat light on the model look that much darker.', '2008-06-04 01:32:06.000000', NULL, 0);
