(4746917, 682292, 82985, '<td valign="top"><a href="//www.dpchallenge.com/image.php?IMAGE_ID=677020" rel="nofollow" target="_blank"><img alt="'' . substr(''//images.dpchallenge.com/images_portfolio/80000-84999/82985/120/677020.jpg'', strrpos(''//images.dpchallenge.com/images_portfolio/80000-84999/82985/120/677020.jpg'', ''/'') + 1) . ''" border="0" src="//images.dpchallenge.com/images_portfolio/80000-84999/82985/120/677020.jpg"/></a>PostLuminous Award WINNER!<br/>beautiful, subtle, luminous, with a perfect selective focus, wonderful tones and mood</td>', 'PostLuminous Award WINNER!beautiful, subtle, luminous, with a perfect selective focus, wonderful tones and mood', '2008-06-04 01:46:08.000000', NULL, 0),
