INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4751834, 681964, 3087, '<td valign="top">Beautiful portrait of the very beautiful Hanae. I particularly love that she''s not plastered in make-up as so many of the models used in DPC entries are. The eye contact is electrifying and the lighting (and lovely shadows), the colour and print of the fabric and the composition are just right. <br/> <br/>Well done, Marac!<br/> <br/>Hope you two can make it to Kew in a couple of weeks when Bexxi is visiting?</td>', 'Beautiful portrait of the very beautiful Hanae. I particularly love that she''s not plastered in make-up as so many of the models used in DPC entries are. The eye contact is electrifying and the lighting (and lovely shadows), the colour and print of the fabric and the composition are just right.  Well done, Marac! Hope you two can make it to Kew in a couple of weeks when Bexxi is visiting?', '2008-06-05 14:29:25.000000', NULL, 0),
(4751895, 681577, 33769, '<td valign="top">I gave this a 10 -its great!  the lighting is beautiful - focus is RIGHT ON THE $ - the shapes are beautiful and its an image I would hang in my kitchen or somewhere with pastel colors- - the colors are amazing, and I LOVE :P  :)  <br/> <br/>great first image entry BTW!! :) :-D is this a pet? looks like one = well kept etc.. :) <br/> <br/>great image look forward to seeing more of your entires! :)<br/> <br/>ETA: OBVIOUSLY this is a female also so it fits the challenge :P <br/><br/><i>Message edited by author 2008-06-05 13:53:18.</i></td>', 'I gave this a 10 -its great!  the lighting is beautiful - focus is RIGHT ON THE $ - the shapes are beautiful and its an image I would hang in my kitchen or somewhere with pastel colors- - the colors are amazing, and I LOVE :P  :)   great first image entry BTW!! :) :-D is this a pet? looks like one = well kept etc.. :)  great image look forward to seeing more of your entires! :) ETA: OBVIOUSLY this is a female also so it fits the challenge :P ', '2008-06-05 14:52:40.000000', '2008-06-05 14:53:18.000000', 0),
